CREATE TABLE IF NOT EXISTS roles(id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(100), description VARCHAR(255));
CREATE TABLE IF NOT EXISTS permissions(id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, description VARCHAR(255));
CREATE TABLE IF NOT EXISTS role_permissions(role_id BIGINT REFERENCES roles(id), permission_id BIGINT REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS accounts(id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(200) NOT NULL, role_id BIGINT NOT NULL REFERENCES roles(id), status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS employees(id BIGINT AUTO_INCREMENT PRIMARY KEY, account_id BIGINT NOT NULL UNIQUE REFERENCES accounts(id), employee_code VARCHAR(30) NOT NULL UNIQUE, status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS registers(id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS shifts(id BIGINT AUTO_INCREMENT PRIMARY KEY, shift_no VARCHAR(30) NOT NULL UNIQUE, employee_id BIGINT NOT NULL REFERENCES employees(id), register_id BIGINT NOT NULL REFERENCES registers(id), status VARCHAR(10) NOT NULL DEFAULT 'OPEN', open_request_key VARCHAR(64) NOT NULL UNIQUE, opened_at TIMESTAMP NOT NULL, closed_at TIMESTAMP, opening_cash DECIMAL(18,2) NOT NULL CHECK(opening_cash>=0), open_employee_id BIGINT GENERATED ALWAYS AS (CASE WHEN status='OPEN' THEN employee_id ELSE NULL END), UNIQUE(open_employee_id));
CREATE TABLE IF NOT EXISTS product_categories(id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS units(id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(12) NOT NULL UNIQUE, name VARCHAR(50) NOT NULL, quantity_scale INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS products(id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(20) NOT NULL UNIQUE, barcode VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL, category_id BIGINT NOT NULL REFERENCES product_categories(id), unit_id BIGINT NOT NULL REFERENCES units(id), sale_price DECIMAL(18,2) NOT NULL CHECK(sale_price>0), stock_quantity DECIMAL(15,3) NOT NULL DEFAULT 0, reserved_quantity DECIMAL(15,3) NOT NULL DEFAULT 0, status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE', image_url VARCHAR(500), stopped_at TIMESTAMP, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CHECK(stock_quantity>=0 AND reserved_quantity>=0 AND reserved_quantity<=stock_quantity));
CREATE TABLE IF NOT EXISTS orders(id BIGINT AUTO_INCREMENT PRIMARY KEY, order_no VARCHAR(30) NOT NULL UNIQUE, shift_id BIGINT NOT NULL REFERENCES shifts(id), status VARCHAR(12) NOT NULL DEFAULT 'DRAFT', subtotal_amount DECIMAL(18,2) NOT NULL DEFAULT 0, discount_amount DECIMAL(18,2) NOT NULL DEFAULT 0, total_amount DECIMAL(18,2) NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL, paid_at TIMESTAMP, cancelled_at TIMESTAMP, cancellation_reason VARCHAR(255), create_request_key VARCHAR(64) NOT NULL UNIQUE, CHECK(status IN ('DRAFT','PENDING','PAID','CANCELLED')), CHECK(total_amount=subtotal_amount-discount_amount));
CREATE TABLE IF NOT EXISTS order_items(id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id), product_id BIGINT NOT NULL REFERENCES products(id), product_code_snapshot VARCHAR(20) NOT NULL, product_name_snapshot VARCHAR(200) NOT NULL, barcode_snapshot VARCHAR(50) NOT NULL, unit_code_snapshot VARCHAR(12) NOT NULL, quantity DECIMAL(15,3) NOT NULL CHECK(quantity>0), unit_price DECIMAL(18,2) NOT NULL, promotion_id BIGINT, promotion_code_snapshot VARCHAR(20), promotion_name_snapshot VARCHAR(200), discount_amount DECIMAL(18,2) NOT NULL DEFAULT 0, line_total DECIMAL(18,2) NOT NULL, UNIQUE(order_id,product_id), CHECK(line_total=ROUND(quantity*unit_price,2)-discount_amount));
CREATE TABLE IF NOT EXISTS payments(id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id), method VARCHAR(16) NOT NULL, status VARCHAR(10) NOT NULL, amount_due DECIMAL(18,2) NOT NULL, amount_received DECIMAL(18,2) NOT NULL DEFAULT 0, change_amount DECIMAL(18,2) NOT NULL DEFAULT 0, idempotency_key VARCHAR(64) NOT NULL UNIQUE, bank_reference VARCHAR(100) UNIQUE, confirmed_by BIGINT REFERENCES accounts(id), confirmed_at TIMESTAMP, created_at TIMESTAMP NOT NULL, completed_at TIMESTAMP, success_order_id BIGINT GENERATED ALWAYS AS(CASE WHEN status='SUCCESS' THEN order_id ELSE NULL END), pending_order_id BIGINT GENERATED ALWAYS AS(CASE WHEN status='PENDING' THEN order_id ELSE NULL END), UNIQUE(success_order_id), UNIQUE(pending_order_id), UNIQUE(id,order_id), CHECK(method IN ('CASH','BANK_TRANSFER')), CHECK(status IN ('SUCCESS','FAILED','PENDING')));
CREATE TABLE IF NOT EXISTS invoices(id BIGINT AUTO_INCREMENT PRIMARY KEY, invoice_no VARCHAR(30) NOT NULL UNIQUE, order_id BIGINT NOT NULL UNIQUE REFERENCES orders(id), payment_id BIGINT NOT NULL UNIQUE REFERENCES payments(id), issued_by BIGINT NOT NULL REFERENCES accounts(id), cashier_name_snapshot VARCHAR(200) NOT NULL, issued_at TIMESTAMP NOT NULL, subtotal_amount DECIMAL(18,2) NOT NULL, discount_amount DECIMAL(18,2) NOT NULL, total_amount DECIMAL(18,2) NOT NULL, status VARCHAR(10) NOT NULL DEFAULT 'ISSUED', CHECK(total_amount=subtotal_amount-discount_amount));
CREATE TABLE IF NOT EXISTS inventory_movements(id BIGINT AUTO_INCREMENT PRIMARY KEY, event_key VARCHAR(64) NOT NULL UNIQUE, product_id BIGINT REFERENCES products(id), product_code_snapshot VARCHAR(20) NOT NULL, order_item_id BIGINT REFERENCES order_items(id), movement_type VARCHAR(10) NOT NULL, quantity_delta DECIMAL(15,3) NOT NULL, reason VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL);
